export interface LeadCapture {
  leadCaptureId: number;
  companyId: number | null; // Nullable based on DB spec and ADR-001
  fullName: string;
  email: string;
  companyName: string | null;
  phone: string | null;
  jobTitle: string | null;
  message: string | null;
  leadSource: string;
  interestArea: string | null;
  status: string;
  assignedTo: number | null; // FK to employees, nullable
  privacyConsentAccepted: boolean;
  created_At: string;
  updated_at: string | null;
}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

// For create, some fields are automatically set by backend or not applicable
export type CreateLeadCapturePayload = Omit<LeadCapture, "leadCaptureId" | "created_At" | "updated_at" | "status" | "assignedTo"> & {
  companyId?: number; // Optional for internal creates, for public it's null
  status?: string;    // Can be specified internally, but backend defaults for public
  assignedTo?: number; // Can be specified internally, but usually assigned later
};

// GET ALL — POST /all_leadCaptures
export async function getAllLeadCaptures(companyId: number): Promise<LeadCapture[]> {
  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "companyId": companyId }] }), // Filter by companyId for internal lists
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? [];
}

// GET ONE — POST /one_leadCaptures
export async function getLeadCapture(id: number, companyId: number): Promise<LeadCapture | null> {
  const res = await fetch(BASE_URL + "/one_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "leadCaptureId": id, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures?.[0] ?? null;
}

// CREATE — action: 1
export async function createLeadCapture(payload: CreateLeadCapturePayload): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 1, ...payload }] }),
  });
