      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Captura de Leads — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          value={searchText}
          onIonInput={(e: CustomEvent<HTMLIonSearchbarElement>) => setSearchText(e.detail.value!)}
          placeholder="Buscar leads..."
          debounce={300}
          className="lead-capture-searchbar"
        />

        <div className="lead-capture-filters">
          <IonSelect
            value={filterStatus}
            placeholder="Filtrar por Estatus"
            onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => setFilterStatus(e.detail.value)}
            fill="outline"
            label="Estatus"
            labelPlacement="floating"
            className="lead-capture-select"
          >
            <IonSelectOption value="">Todos</IonSelectOption>
            {LEAD_STATUS_OPTIONS.map(opt => (
              <IonSelectOption key={opt.value} value={opt.value}>{opt.label}</IonSelectOption>
            ))}
          </IonSelect>

          <IonSelect
            value={filterInterestArea}
            placeholder="Filtrar por Área de Interés"
            onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => setFilterInterestArea(e.detail.value)}
            fill="outline"
            label="Área de Interés"
            labelPlacement="floating"
            className="lead-capture-select"
          >
            <IonSelectOption value="">Todas</IonSelectOption>
            {INTEREST_AREA_OPTIONS.map(opt => (
              <IonSelectOption key={opt.value} value={opt.value}>{opt.label}</IonSelectOption>
            ))}
          </IonSelect>
        </div>

        <IonList className="lead-capture-list">
          {loading && leads.length === 0 ? (
            <div className="ion-text-center ion-padding">
              <IonSpinner name="crescent" />
              <p>Cargando leads...</p>
            </div>
          ) : leads.length === 0 ? (
            <IonItem>
              <IonLabel>No hay leads disponibles.</IonLabel>
            </IonItem>
          ) : (
            leads.map(lead => (
              <IonItem key={lead.leadCaptureId} detail onClick={() => handleOpenDetailModal(lead)} className="lead-capture-item">
                <IonLabel>
                  <h2>{lead.fullName}</h2>
                  <p>{lead.email} - {lead.phone}</p>
                  <p>Empresa: {lead.companyName ?? 'N/A'}</p>
                  <p>Fuente: {lead.leadSource}</p>
                  <p>Área de Interés: {lead.interestArea ?? 'N/A'}</p>
                  <p>Creado: {toHermosillo(lead.created_At)}</p>
                </IonLabel>
                <IonBadge slot="end" color={getStatusColor(lead.status)} className="lead-capture-status-chip">
                  {LEAD_STATUS_OPTIONS.find(opt => opt.value === lead.status)?.label || lead.status}
                </IonBadge>
              </IonItem>
            ))
          )}
        </IonList>

        <IonInfiniteScroll
          onIonInfinite={loadMoreLeads}
          threshold="100px"
          disabled={!hasMore}
        >
          <IonInfiniteScrollContent loadingText="Cargando más leads..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={handleOpenCreateModal} disabled={!canEdit}>
            <IonIcon icon={addOutline} />
          </IonFabButton>
        </IonFab>

        {/* Create/Edit Lead Modal */}
        <IonModal isOpen={showCreateModal || showDetailModal} onDidDismiss={handleCloseModal} className="lead-capture-modal">
          <IonHeader>
            <IonToolbar>
              <IonTitle>{selectedLead ? 'Editar Lead' : 'Crear Nuevo Lead'}</IonTitle>
              <IonButtons slot="end">
                <IonButton onClick={handleCloseModal}>Cerrar</IonButton>
              </IonButtons>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <div className="lead-capture-form">
              <IonInput
                fill="outline"
                label="Nombre Completo *"
                labelPlacement="floating"
                value={formState.fullName}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setFormState(p => ({ ...p, fullName: e.detail.value! }))}
                className={fullNameError ? 'ion-invalid ion-touched' : ''}
                errorText={fullNameError}
                disabled={!canEdit}
              />

              <IonInput
                fill="outline"
                label="Email *"
                labelPlacement="floating"
                type="email"
                value={formState.email}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setFormState(p => ({ ...p, email: e.detail.value! }))}
                className={emailError ? 'ion-invalid ion-touched' : ''}
                errorText={emailError}
                disabled={!canEdit}
              />

              <IonInput
                fill="outline"
                label="Nombre de la Empresa"
                labelPlacement="floating"
                value={formState.companyName}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setFormState(p => ({ ...p, companyName: e.detail.value! }))}
                disabled={!canEdit}
              />

              <IonInput
                fill="outline"
                label="Teléfono"
                labelPlacement="floating"
                type="tel"
                value={formState.phone}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setFormState(p => ({ ...p, phone: e.detail.value! }))}
                disabled={!canEdit}
              />

              <IonInput
                fill="outline"
                label="Puesto"
                labelPlacement="floating"
                value={formState.jobTitle}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setFormState(p => ({ ...p, jobTitle: e.detail.value! }))}
                disabled={!canEdit}
              />

              <IonInput
                fill="outline"
                label="Mensaje"
                labelPlacement="floating"
                value={formState.message}
                onIonInput={(e: CustomEvent<HTMLIonInputElement>) => setFormState(p => ({ ...p, message: e.detail.value! }))}
                disabled={!canEdit}
              />

              <IonSelect
                fill="outline"
                label="Fuente del Lead *"
                labelPlacement="floating"
                value={formState.leadSource}
                onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => setFormState(p => ({ ...p, leadSource: e.detail.value! }))}
                className={leadSourceError ? 'ion-invalid ion-touched' : ''}
                errorText={leadSourceError}
                disabled={!canEdit}
              >
                {LEAD_SOURCE_OPTIONS.map(opt => (
                  <IonSelectOption key={opt.value} value={opt.value}>{opt.label}</IonSelectOption>
                ))}
              </IonSelect>

              <IonSelect
                fill="outline"
                label="Área de Interés"
                labelPlacement="floating"
                value={formState.interestArea}
                onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => setFormState(p => ({ ...p, interestArea: e.detail.value! }))}
                disabled={!canEdit}
              >
                <IonSelectOption value="">Seleccionar</IonSelectOption>
                {INTEREST_AREA_OPTIONS.map(opt => (
                  <IonSelectOption key={opt.value} value={opt.value}>{opt.label}</IonSelectOption>
                ))}
              </IonSelect>

              {selectedLead && (
                <IonSelect
                  fill="outline"
                  label="Estatus"
                  labelPlacement="floating"
                  value={formState.status}
                  onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => setFormState(p => ({ ...p, status: e.detail.value! }))}
                  disabled={!canEdit}
                >
                  {LEAD_STATUS_OPTIONS.map(opt => (
                    <IonSelectOption key={opt.value} value={opt.value}>{opt.label}</IonSelectOption>
                  ))}
                </IonSelect>
              )}

              {selectedLead && (
                <IonSelect
                  fill="outline"
                  label="Asignado a"
                  labelPlacement="floating"
                  value={formState.assignedTo}
                  onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => setFormState(p => ({ ...p, assignedTo: e.detail.value === null ? null : Number(e.detail.value) }))}
                  disabled={!canEdit}
                >
                  <IonSelectOption value={null}>No asignado</IonSelectOption>
                  {DUMMY_EMPLOYEES.map(emp => (
                    <IonSelectOption key={emp.employeeId} value={emp.employeeId}>{emp.fullName}</IonSelectOption>
                  ))}
                </IonSelect>
              )}

              <IonItem lines="none" className="ion-no-padding">
                <IonToggle
                  checked={formState.privacyConsentAccepted}
                  onIonChange={(e: CustomEvent<HTMLIonToggleElement>) => setFormState(p => ({ ...p, privacyConsentAccepted: e.detail.checked }))}
                  labelPlacement="end"
                  className={privacyConsentError ? 'ion-invalid ion-touched' : ''}
                  disabled={!canEdit}
                >
                  Aceptar política de privacidad *
                </IonToggle>
              </IonItem>
              {privacyConsentError && <p className="ion-text-danger ion-padding-start">{privacyConsentError}</p>}

              {selectedLead && (
                <IonItem className="lead-capture-info-item">
                  <IonLabel>
                    <p>ID: {selectedLead.leadCaptureId}</p>
                    <p>Empresa ID: {selectedLead.companyId ?? 'N/A'}</p>
                    <p>Creado: {toHermosillo(selectedLead.created_At)}</p>
                    <p>Actualizado: {toHermosillo(selectedLead.updated_at)}</p>
                  </IonLabel>
                </IonItem>
              )}
            </div>
          </IonContent>
          <IonFooter className="lead-capture-modal-footer">
            <IonToolbar>
              {selectedLead ? (
                <div className="ion-padding-horizontal ion-padding-vertical lead-capture-footer-actions">
                  <IonButton expand="block" fill="clear" color="danger" onClick={() => handleDeleteClick(selectedLead.leadCaptureId)} disabled={!canEdit || saving}>
                    <IonIcon icon={trashOutline} slot="start" />
                    Eliminar
                  </IonButton>
                  <IonButton expand="block" onClick={handleUpdateLead} disabled={!canEdit || saving}>
                    {saving ? <IonSpinner name="dots" /> : <><IonIcon icon={pencilOutline} slot="start" /> Guardar Cambios</>}
                  </IonButton>
                </div>
              ) : (
                <IonButton expand="block" onClick={handleSaveNewLead} disabled={!canEdit || saving} className="ion-margin">
                  {saving ? <IonSpinner name="dots" /> : 'Crear Lead'}
                </IonButton>
              )}
            </IonToolbar>
          </IonFooter>
        </IonModal>

        <IonLoading isOpen={loading && leads.length === 0} message="Cargando..." />
        <IonToast
          isOpen={showToast}
          message={toastMessage}
          duration={3000}
          onDidDismiss={() => setShowToast(false)}
          color={error ? 'danger' : 'success'}
        />

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={'¿Estás seguro de que quieres eliminar este lead? Esta acción no se puede deshacer.'}
          buttons={[
            { text: 'Cancelar', role: 'cancel', handler: () => setLeadToDeleteId(null) },
            { text: 'Eliminar', handler: handleConfirmDelete, cssClass: 'danger-button' },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default LeadCapturePage;
